use vstd::prelude::*;

verus! {

fn append_array(a: &[i32], b: &[i32]) -> (c: Vec<i32>)
    ensures
        c.len() == a.len() + b.len(),
        // all elements of a are preserved in c
        forall |k: usize| k < a.len() ==> c[k] == a[k],
        // all elements of b are appended after a
        forall |k: usize| k < b.len() ==> c[a.len() + k] == b[k],
{
    // start with an empty vector
    let mut c: Vec<i32> = Vec::new();
    // optional: reserve capacity to avoid re‐allocations
    c.reserve(a.len() + b.len());

    // first, copy all elements of a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            // the vector c so far has length i, and matches a[0..i]
            c.len() == i,
            forall |k: usize| k < i ==> c[k] == a[k],
        decreases a.len() - i
    {
        c.push(a[i]);
        i += 1;
    }

    // remember the length of a for indexing b
    let alen = a.len();

    // next, copy all elements of b
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            // after copying j elements of b, c.len() = alen + j
            c.len() == alen + j,
            // the prefix from a is still correct
            forall |k: usize| k < alen ==> c[k] == a[k],
            // the part copied from b so far is correct
            forall |k: usize| k < j ==> c[alen + k] == b[k],
        decreases b.len() - j
    {
        c.push(b[j]);
        j += 1;
    }

    c
}

}

